const numeros = [10, 2, 1, 20];

const crescente = numeros.slice().sort((a, b) => a - b);
console.log(crescente); // [1, 2, 10, 20] — comparação numérica!

console.log([10, 2, 1].sort()); // [1, 10, 2] — sem comparação vira texto!

const invertida = numeros.slice().reverse();
console.log(invertida); // [20, 1, 2, 10]
console.log(numeros);   // [10, 2, 1, 20] — a original não mudou

// Passo 1: conferimos que veio uma lista de verdade.
function ordenarSemSujar(lista) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }

  // Passo 2: copia antes — sort mexe na lista que recebe.
  const copia = lista.slice();

  // Passo 3: ordena a cópia com comparação de números.
  return copia.sort((a, b) => a - b);
}

const original = [10, 2, 1, 20];
console.log(ordenarSemSujar(original)); // [1, 2, 10, 20]
console.log(original);                  // [10, 2, 1, 20] — intacta
